"rb_homey_find":{"message0":"apparatus Homey congruentes cum %1","tooltip":"Index schedarum, una pro quoque apparatu cuius nomen, zona aut genus omnia haec verba continet («*» pro omnibus): name, zone, class et quisque valor eius."},
"rb_homey_flow":{"message0":"exsequere fluxum operis Homey %1","tooltip":"Unum ex fluxibus operis Homey tuis nomine incipit. Fluxus quidquid Homey tuus potest facere potest, etiam monitionem Homey mittere."},
