"rb_tg_when":{"message0":"cum nuntius Telegram advenit continens %1","tooltip":"Lateres infra exsequitur cum automaton tuum nuntium accipit (scribe «anything», aut verba quae nuntius continere debet). Solum nuntii ex colloquiis tuis numerantur (TELEGRAM_CHAT_ID). In Python exportato semper auscultat; in hac pagina, dextra preme et elige «Exsequere hoc scriptum» ut cum nuntio exemplari experiaris."},
"rb_timer":{"message0":"horologium","tooltip":"Secunda ex quo exsecutio coepit aut horologium renovatum est."},
"rb_tokens_used":{"message0":"signa adhuc consumpta","tooltip":"Signa quae haec exsecutio consumpsit: missa et accepta. Aestimatio in hac pagina, accurata in Python exportato."},
"rb_try":{"message0":"tempta","message1":"%1","message2":"si deficit","message3":"%1","tooltip":"Primam partem exsequitur. Si quid in ea deficit, secundam partem exsequitur pro exsecutione sistenda."},
"rb_use_model":{"message0":"utere exemplari %1","tooltip":"Exemplar muta pro lateribus IA post hunc. Exemplaria praeter Claude in Python exportato currunt; in hac pagina Claude pro eis stat."},
"rb_wait":{"message0":"exspecta %1 %2","tooltip":"Hoc scriptum siste (usque ad 24 horas)."},
"rb_wait_msg":{"message0":"exspecta donec accipiam %1","tooltip":"Hoc scriptum siste donec aliud scriptum nuntium praedicet."},
"rb_wait_time":{"message0":"exspecta usque ad %1 : %2","tooltip":"Siste usque ad hanc horam (horologio 24 horarum). Si hodie praeteriit, usque ad crastinum exspectat."},
"rb_wait_until":{"message0":"exspecta donec %1","tooltip":"Siste donec condicio vera sit. Bis in secundo inspicitur, aut singulis 10 secundis si Claude interrogat."},
"rb_web_search":{"message0":"quaere in interreti %1","tooltip":"In Python exportato interrete vivum quaerit. In hac pagina Claude navigare non potest, itaque ex sua scientia respondet et acta id dicunt."},
"rb_webhook_when":{"message0":"cum petitio interretialis advenit ad / %1","tooltip":"Lateres infra exsequitur cum aliquid (Home Assistant, IFTTT, compendium in telephono tuo) vocat http://<hic computatrum>:8765/bake-done?key=<WEBHOOK_SECRET>. Petitiones sine clave reiciuntur. «Quod advenit» dat textum missum, et campos JSON aut inscriptionis."},
"rb_when_time":{"message0":"cum est %1 : %2 %3","tooltip":"Hac hora currit (horologio 24 horarum) dum Horaria accensa sunt et haec pagina aperta est."},
"rb_with_any_model":{"message0":"cum exemplari OpenRouter %1","message1":"%1","tooltip":"Solum lateres intus in quolibet exemplari quod OpenRouter praebet exsequitur. Nomen eius ex openrouter.ai/models scribe, exempli gratia mistralai/mistral-small aut google/gemma-4-31b-it. openrouter/auto unum pro te eligit. In Python exportato currit (OPENROUTER_API_KEY eget); in hac pagina Claude pro eo stat."},
"rb_with_model":{"message0":"cum exemplari %1","message1":"%1","tooltip":"Solum lateres intus in hoc exemplari exsequitur, deinde ad exemplar prius redit. Exemplaria praeter Claude in Python exportato currunt; in hac pagina Claude pro eis stat."},
"rb_word_count":{"message0":"numerus verborum %1"}
